class Solution {
public:
    string addSpaces(string s, vector<int>& spaces) {
        string result;
        result.reserve(s.size() + spaces.size());
        int j = 0;
        int m = (int)spaces.size();
        for (int i = 0; i < (int)s.size(); i++) {
            if (j < m && spaces[j] == i) {
                result.push_back(' ');
                j++;
            }
            result.push_back(s[i]);
        }
        return result;
    }
};
